breaking_changes.Adaptation_method:
// Before:
const Response = require('node-fetch/lib/response');

// After:
const { Response } = require('node-fetch');
// or
import { Response } from 'node-fetch';

// Before:
const text = await response.text(); // automatic encoding detection

// After (for UTF-8 only):
const text = await response.text();

// After (if auto encoding detection needed, like v1):
const text = await response.textConverted();

// Before (v1):
const data = await response.json(); // data is {} on 204

// After (v2):
try {
  const data = await response.json();
} catch (err) {
  if (response.status === 204) {
    // Handle no-content
    // possibly set data = {} or handle specially
  } else {
    throw err;
  }
}

// Before (v1):
new fetch.Request('https://example.com', { method: 'GET', body: 'data' }); // previously allowed

// After (v2):
// Remove 'body' when using GET or HEAD:
new fetch.Request('https://example.com', { method: 'GET' });

// Before:
const values = headers.getAll('set-cookie');

// After:
const values = headers.get('set-cookie').split(','); // returns all values as a comma-delimited string

// Before:
const value = headers.get('Multi'); // 'header1'

// After:
const value = headers.get('Multi'); // 'header1,header2'
const firstValue = headers.get('Multi').split(',')[0]; // 'header1'

// Before:
headers.set('null-header', null); // get('null-header') returns null
headers.set('undefined', undefined); // get(undefined) throws

// After:
headers.set('null-header', null); // get('null-header') returns 'null'
headers.set('undefined', undefined); // get(undefined) returns 'undefined'
